 IntPtr HotkeyHook(IntPtr hwnd,int msg,IntPtr w,IntPtr l,ref bool handled){if(msg==0x312&&w.ToInt32()==5781){ShowPicker();handled=true;}return IntPtr.Zero;}
 void ShowPicker(){Show();if(WindowState==WindowState.Minimized)WindowState=WindowState.Normal;Activate();}
 void DisposeFeatures(){featureClosed=true;if(source!=null){if(hotkeyRegistered)UnregisterHotKey(source.Handle,5781);source.RemoveHook(HotkeyHook);}if(tray!=null){tray.Visible=false;if(tray.ContextMenuStrip!=null)tray.ContextMenuStrip.Dispose();var icon=tray.Icon;tray.Dispose();if(icon!=null)icon.Dispose();}}
