 string ProfileColor(Profile p,bool active){if(active)return "#31433A";string[] colors={"#343434","#30434A","#42405B","#4A3B32","#3C4836","#4C3743","#334B46"};return colors[Math.Abs(p.Color%colors.Length)];}
