 IdentityInfo Identity(Profile p){IdentityInfo value;if(!identities.TryGetValue(p.Id,out value)||value.CredentialStamp!=AccountService.Stamp(store,p)){identities.Remove(p.Id);value=AccountService.Cached(store,p);}AccountService.ApplyExpected(value,p);return value;}
