 void ApplyLogo(Border avatar,Profile p){try{if(String.IsNullOrEmpty(p.Logo))return;string path=Path.GetFullPath(Path.Combine(store.Root,"ProfileImages",p.Logo));string root=Path.GetFullPath(Path.Combine(store.Root,"ProfileImages"))+Path.DirectorySeparatorChar;if(!path.StartsWith(root,StringComparison.OrdinalIgnoreCase)||!File.Exists(path))return;var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.UriSource=new Uri(path);image.DecodePixelWidth=100;image.EndInit();avatar.Child=new Image{Source=image,Stretch=Stretch.UniformToFill};avatar.Clip=new RectangleGeometry(new Rect(0,0,43,43),13,13);}catch{}}
 void EnableReorder(Button card,string id){Point start=new Point();card.PreviewMouseLeftButtonDown+=(s,e)=>start=e.GetPosition(card);card.MouseMove+=(s,e)=>{if(e.LeftButton!=MouseButtonState.Pressed||busy)return;Point now=e.GetPosition(card);if(Math.Abs(now.X-start.X)<SystemParameters.MinimumHorizontalDragDistance&&Math.Abs(now.Y-start.Y)<SystemParameters.MinimumVerticalDragDistance)return;suppressClickUntil=DateTime.UtcNow.AddSeconds(2);DragDrop.DoDragDrop(card,new DataObject("OpenAIProfiles.ProfileId",id),DragDropEffects.Move);};card.AllowDrop=true;card.DragOver+=(s,e)=>{e.Effects=e.Data.GetDataPresent("OpenAIProfiles.ProfileId")?DragDropEffects.Move:DragDropEffects.None;e.Handled=true;};card.Drop+=(s,e)=>{if(busy)return;string other=e.Data.GetData("OpenAIProfiles.ProfileId")as string;if(other==null)return;try{store.Move(other,id);Rebuild();RefreshTray();}catch(Exception ex){Error(ex);}e.Handled=true;};}
 MenuItem Item(ContextMenu menu,string label,Action action){var item=new MenuItem{Header=label};item.Click+=(s,e)=>action();menu.Items.Add(item);return item;}
 void ExtendProfileMenu(ContextMenu menu,string id){var p=store.State.Profiles.Single(x=>x.Id==id);
  Item(menu,p.Favorite?"Remove from favorites":"Add to favorites",()=>{store.Edit(id,x=>x.Favorite=!x.Favorite);Rebuild();RefreshTray();});
  Item(menu,"Identity & workspace",()=>IdentityPanel(id));
  Item(menu,"Check account with native service",async()=>await RunCheck("Checking native identity",async()=>{var info=await Task.Run(()=>AccountService.Verify(store,p));identities[id]=info;Rebuild();Report("Account verification",info.Display+(info.Mismatch?"\nLaunch is blocked until the expected identity is corrected.":""));}));
  Item(menu,"Verify shared history",async()=>await RunCheck("Checking shared history",async()=>{var result=await Task.Run(()=>HealthService.History(store,p));Report(result.Success?"Shared history check passed":"History needs attention",result.Text);}));
  Item(menu,"Customize profile",()=>Customize(id));
  Item(menu,"Move earlier",()=>MoveStep(id,-1));Item(menu,"Move later",()=>MoveStep(id,1));
  Item(menu,"Create desktop shortcut",()=>CreateShortcut(p));
 }
 void MoveStep(string id,int delta){var list=store.Ordered();int index=list.FindIndex(x=>x.Id==id);int target=index+delta;if(target<0||target>=list.Count)return;if(delta<0)store.Move(id,list[target].Id);else store.Move(list[target].Id,id);Rebuild();RefreshTray();}
 async Task RunCheck(string heading,Func<Task> action){if(busy)return;busy=true;cards.IsEnabled=false;addButton.IsEnabled=false;try{Status(heading,"Please wait. No model prompt is sent.");await action();Status("Check complete","Choose a profile when you're ready.");}catch(Exception ex){Error(ex);Status("Check could not complete","Your account and history have not been switched.");}finally{busy=false;cards.IsEnabled=true;addButton.IsEnabled=true;}}
 public void Report(string heading,string body){var d=Dialog(heading,"",330);var panel=DialogPanel(d);var text=new TextBox{Text=body,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,Foreground=B("#C8C8C8"),Background=Brushes.Transparent,BorderThickness=new Thickness(0),FontSize=12,MaxHeight=340,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(0,5,0,20)};panel.Children.Add(text);var done=new Button{Content="Done",Style=(Style)d.FindResource("Primary"),HorizontalAlignment=HorizontalAlignment.Right,IsDefault=true,IsCancel=true};done.Click+=(s,e)=>d.Close();panel.Children.Add(done);d.ShowDialog();}
 bool ConfirmAction(string heading,string body,string action,int height=270){var d=Dialog(heading,body,height);var row=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,20,0,0)};var cancel=new Button{Content="Cancel",Style=(Style)d.FindResource("Quiet"),IsCancel=true,Margin=new Thickness(0,0,8,0)};cancel.Click+=(s,e)=>d.DialogResult=false;var go=new Button{Content=action,Style=(Style)d.FindResource("Primary")};go.Click+=(s,e)=>d.DialogResult=true;row.Children.Add(cancel);row.Children.Add(go);DialogPanel(d).Children.Add(row);return d.ShowDialog()==true;}
 void IdentityPanel(string id){var p=store.State.Profiles.Single(x=>x.Id==id);var info=Identity(p);var d=Dialog("Identity & workspace",info.Display,420);var panel=DialogPanel(d);panel.Children.Add(Txt("Expected email (optional)",11,"#A0A0A0",FontWeights.Normal));var email=new TextBox{Text=p.ExpectedEmail??"",Style=(Style)d.FindResource("Field"),Margin=new Thickness(0,6,0,14)};panel.Children.Add(email);panel.Children.Add(Txt("Expected workspace ID (optional)",11,"#A0A0A0",FontWeights.Normal));var workspace=new TextBox{Text=p.ExpectedWorkspace??"",Style=(Style)d.FindResource("Field"),Margin=new Thickness(0,6,0,20)};panel.Children.Add(workspace);var save=new Button{Content="Save identity guard",Style=(Style)d.FindResource("Primary"),HorizontalAlignment=HorizontalAlignment.Right};save.Click+=(s,e)=>{store.Edit(id,x=>{x.ExpectedEmail=email.Text.Trim();x.ExpectedWorkspace=workspace.Text.Trim();});identities.Remove(id);Rebuild();d.Close();};panel.Children.Add(save);d.ShowDialog();}
 void Customize(string id){var p=store.State.Profiles.Single(x=>x.Id==id);var d=Dialog("Customize profile","Set an avatar color or choose a company logo.",310);var panel=DialogPanel(d);var colors=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,20,0,20)};for(int i=0;i<7;i++){int color=i;var sample=new Profile{Color=i};var button=new Button{Width=34,Height=34,Margin=new Thickness(0,0,10,0),Background=B(ProfileColor(sample,false)),BorderBrush=B(p.Color%7==i?"#EEEEEE":"#666666"),BorderThickness=new Thickness(2)};button.Click+=(s,e)=>{store.Edit(id,x=>x.Color=color);Rebuild();d.Close();};colors.Children.Add(button);}panel.Children.Add(colors);
  var logo=Btn("Choose logo image…","Quiet");logo.Click+=(s,e)=>{var pick=new OpenFileDialog{Filter="Images|*.png;*.jpg;*.jpeg;*.ico",Multiselect=false};if(pick.ShowDialog(d)!=true)return;try{var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.UriSource=new Uri(pick.FileName);image.DecodePixelWidth=192;image.EndInit();string root=Path.Combine(store.Root,"ProfileImages");Directory.CreateDirectory(root);string file=Guid.NewGuid().ToString("N")+".png";var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using(var stream=File.Create(Path.Combine(root,file)))encoder.Save(stream);store.Edit(id,x=>x.Logo=file);Rebuild();d.Close();}catch(Exception ex){Error(ex);}};panel.Children.Add(logo);var clear=Btn("Remove custom logo","Quiet");clear.Click+=(s,e)=>{store.Edit(id,x=>x.Logo=null);Rebuild();d.Close();};panel.Children.Add(clear);var done=Btn("Done","Primary");done.HorizontalAlignment=HorizontalAlignment.Right;done.Margin=new Thickness(0,14,0,0);done.Click+=(s,e)=>d.Close();panel.Children.Add(done);d.ShowDialog();}
 public static string WriteProfileShortcut(ProfileStore profileStore,Profile p,string destinationDirectory,string launcher){
  if(p.Removed)throw new Exception("Restore this profile before creating a shortcut.");Directory.CreateDirectory(destinationDirectory);string name=String.Concat(p.Name.Select(c=>Path.GetInvalidFileNameChars().Contains(c)?'_':c));string path=Path.Combine(destinationDirectory,"OpenAI - "+name+" - "+p.Id+".lnk");
  Type type=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(type);dynamic link=null;try{link=shell.CreateShortcut(path);link.TargetPath=launcher;link.Arguments="--launch "+p.Id+" --profile-root \""+profileStore.Root+"\"";link.WorkingDirectory=Path.GetDirectoryName(launcher);link.Description="Open native ChatGPT profile (single-account guard applies)";link.Save();return path;}finally{if(link!=null)Marshal.FinalReleaseComObject(link);Marshal.FinalReleaseComObject(shell);}
 }
 void CreateShortcut(Profile p){try{WriteProfileShortcut(store,p,Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),System.Reflection.Assembly.GetExecutingAssembly().Location);Status("Shortcut created","A desktop shortcut was created for "+p.Name+".");}catch(Exception ex){Error(ex);}}

