public partial class PremiumPicker {
 void ToolsMenu(){var menu=new ContextMenu();menu.Resources.MergedDictionaries.Add((ResourceDictionary)System.Windows.Markup.XamlReader.Parse(Styles));
  Item(menu,"Backup & restore",()=>BackupPanel());
  Item(menu,"Export safe diagnostics",()=>{var save=new SaveFileDialog{Filter="JSON report|*.json",FileName="OpenAIProfiles-diagnostics.json"};if(save.ShowDialog(this)!=true)return;try{DiagnosticService.Export(store,save.FileName);Report("Diagnostics exported","The report contains only technical status and counts. It excludes login tokens, email addresses, profile names, paths, chat text and raw logs.");}catch(Exception ex){Error(ex);}});
  Item(menu,"Check native app compatibility",async()=>await RunCheck("Checking native app",async()=>{var result=await Task.Run(()=>CompatibilityService.Check());Report("Native app compatibility",result.Version+"\n\n"+result.Message);}));
  Item(menu,"Retry last launch",async()=>{if(lastFailedProfile==null){Report("Nothing to retry","No launch failure has been recorded in this picker session.");return;}await RequestOpen(lastFailedProfile);});
  Item(menu,"Check for launcher updates",async()=>await CheckUpdate());
  Item(menu,"Update settings",()=>UpdateSettings());
  Item(menu,"Minimize to tray",()=>{if(tray!=null){Hide();tray.ShowBalloonTip(2500,"OpenAI Profiles","Double-click the tray icon or press "+pickerHotkey+" to return.",System.Windows.Forms.ToolTipIcon.Info);}});
  Item(menu,"Shortcuts & version",()=>Report("OpenAI Profiles "+ReleaseService.Version,"Ctrl+F: search profiles\n"+pickerHotkey+": show picker from anywhere"+(hotkeyRegistered?"":" (unavailable; Windows error "+hotkeyError+")")+"\nCtrl+Alt+1…9: open favorite profiles while picker is focused\nDrag cards to reorder; right-click for profile tools.\nClosing the picker exits it. Tools > Minimize to tray keeps it running.\n\nThis is an independent utility, not an official OpenAI feature.\nCloud chats and workspace policies remain account-specific."));
  menu.PlacementTarget=Find<Button>("ToolsButton");menu.Placement=System.Windows.Controls.Primitives.PlacementMode.Bottom;menu.IsOpen=true;
 }
 void BackupPanel(){var d=Dialog("Backup & restore","Backups cover local databases. Logins are excluded. Keep profile folders: history may refer to their attachments and rollout files.",410);var panel=DialogPanel(d);var list=new ListBox{Background=B("#1B1B1B"),Foreground=B("#DDDDDD"),BorderBrush=B("#444444"),Height=160,Margin=new Thickness(0,18,0,16)};Action reload=()=>{list.Items.Clear();foreach(string path in BackupService.List(store))list.Items.Add(new ListBoxItem{Content=Path.GetFileName(path),Tag=path});};reload();panel.Children.Add(list);var row=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};var create=Btn("Back up now","Quiet");var restore=Btn("Restore selected","Primary");create.Margin=new Thickness(0,0,9,0);create.Click+=async(s,e)=>{if(busy)return;busy=true;row.IsEnabled=false;try{await Task.Run(()=>BackupService.Create(store));reload();Status("Backup complete","A verified local database backup was created.");}catch(Exception ex){Error(ex);}finally{busy=false;row.IsEnabled=true;}};
  restore.Click+=async(s,e)=>{var selected=list.SelectedItem as ListBoxItem;if(selected==null||busy)return;if(!ConfirmAction("Restore shared local history?","This replaces the current local databases with the selected backup for every profile. A pre-restore backup is kept. Close ChatGPT and all Codex sessions first.\n\nChats created after the snapshot will no longer appear in the restored databases.","Restore history"))return;busy=true;row.IsEnabled=false;try{await Task.Run(()=>BackupService.Restore(store,(string)selected.Tag));reload();Status("History restored","The pre-restore backup is available for recovery.");}catch(Exception ex){Error(ex);}finally{busy=false;row.IsEnabled=true;}};
  row.Children.Add(create);row.Children.Add(restore);panel.Children.Add(row);var done=Btn("Done","Quiet");done.HorizontalAlignment=HorizontalAlignment.Right;done.Margin=new Thickness(0,12,0,0);done.Click+=(s,e)=>{if(!busy)d.Close();};panel.Children.Add(done);d.Closing+=(s,e)=>{if(busy)e.Cancel=true;};d.ShowDialog();
 }
 void UpdateSettings(){var d=Dialog("Update settings","Use your release host and publisher certificate. Downloads must pass checksum and trusted Authenticode verification. No release host is configured by default.",400);var panel=DialogPanel(d);panel.Children.Add(Txt("HTTPS manifest URL",11,"#AAAAAA",FontWeights.Normal));var url=new TextBox{Text=store.State.UpdateManifestUrl??"",Style=(Style)d.FindResource("Field"),Margin=new Thickness(0,6,0,15)};panel.Children.Add(url);panel.Children.Add(Txt("Trusted publisher thumbprint (SHA-1 certificate ID)",11,"#AAAAAA",FontWeights.Normal));var thumb=new TextBox{Text=store.State.PublisherThumbprint??"",Style=(Style)d.FindResource("Field"),Margin=new Thickness(0,6,0,20)};panel.Children.Add(thumb);var save=Btn("Save settings","Primary");save.HorizontalAlignment=HorizontalAlignment.Right;save.Click+=(s,e)=>{try{string value=url.Text.Trim(),pin=thumb.Text.Replace(" ","").Trim();Uri uri;if(value.Length>0&&(!Uri.TryCreate(value,UriKind.Absolute,out uri)||uri.Scheme!="https"))throw new Exception("Use an HTTPS manifest URL.");if(pin.Length>0&&!System.Text.RegularExpressions.Regex.IsMatch(pin,"^[A-Fa-f0-9]{40}$"))throw new Exception("Enter a 40-character publisher certificate thumbprint.");store.Settings(x=>{x.UpdateManifestUrl=value;x.PublisherThumbprint=pin;});d.Close();}catch(Exception ex){Error(ex);}};panel.Children.Add(save);d.ShowDialog();}
 async Task CheckUpdate(){await RunCheck("Checking updates",async()=>{var release=await Task.Run(()=>ReleaseService.Check(store));if(new Version(release.Version)<=new Version(ReleaseService.Version)){Report("You're up to date","Installed version: "+ReleaseService.Version);return;}if(!ConfirmAction("Version "+release.Version+" is available","Download and verify the release? The file will not be run automatically.","Download"))return;string path=await Task.Run(()=>ReleaseService.Download(store,release));Report("Release verified","The SHA-256 checksum and trusted publisher signature passed.\n\nDownload: "+path+"\n\nClose the launcher and run your deployment installer to update. Your current version stays installed for rollback.");});}
